public App()
{
    Logger.InitializeLogger("\\Keyboard Manager\\WinUI3Editor\\Logs");

    string appLanguage = LanguageHelper.LoadLanguage();
    if (!string.IsNullOrEmpty(appLanguage))
    {
        Microsoft.Windows.Globalization.ApplicationLanguages.PrimaryLanguageOverride = appLanguage;
    }

    InitializeComponent();
    UnhandledException += App_UnhandledException;
    SettingsManager.CorrelateServiceAndEditorMappings();
}

// Preferred primary patch: no ResourceHelper change.
// Follow-up only if validation proves necessary:
_resourceLoader = new ResourceLoader("PowerToys.KeyboardManagerEditorUI.pri");

internal static void ApplyLanguageOverride(string language, Action<string> apply)
{
    if (!string.IsNullOrEmpty(language))
    {
        apply(language);
    }
}
